style.css:
@-moz-document domain("music.youtube.com") {
/* MAIN BACKGROUND */
body {
    background-color: #ffd6e7 !important;
}

/* SIDEBAR */
ytmusic-guide-renderer {
    background-color: #ffc0d9 !important;
}

/* TOP BAR */
ytmusic-nav-bar {
    background-color: #ffb3d1 !important;
}

/* PLAYER BAR (bottom music controls) */
ytmusic-player-bar {
    background-color: #ff99c8 !important;
}

/* SONG TITLE + TEXT */
yt-formatted-string,
span,
a {
    color: #5a0033 !important;
}

/* BUTTONS */
ytmusic-button-renderer,
button {
    background-color: #ff80bf !important;
    color: white !important;
    border-radius: 12px !important;
}

/* PROGRESS BAR */
#progress-bar,
.ytmusic-player-bar .progress-bar {
    background-color: #ff4da6 !important;
}
}
